import Foundation
import TerminalDeckNativeCore

/// Exact metadata statically extracted from the five TypeScript area sources.
public enum BackendDeckToolsMachinesCatalogue {
    public static func rows() throws -> [NativeRPCValue] {
        try NativeRPCValue.parseJSON(Data(source.utf8), maximumBytes: 131_072).requireArray("machine area catalogue")
    }
    private static let source = #"""
[{"module":"machine-tools","id":"machines.look","wire":"machines_look","tier":"read","title":"Look at the other computers","description":"The other computers this app is paired to and reaches out to over the internet (other copies of this app, on desktops or servers). With no arguments: every one, whether it is connected, and the sessions running on it. With machineId: that computer in detail — its host, the agent logins it has and its GitHub connection. With machineId and sessionId: one session over there — its screen if this computer is watching it, its model and effort, which login it runs as, and its plan usage and context. Call this first: every other machines tool takes ids from it.","index":"Other paired computers: which are online, their sessions, and one remote session’s screen and settings. Call first.","inputSchema":{"type":"object","properties":{"machineId":{"type":"string","description":"Which computer. Omit to list them all."},"sessionId":{"type":"string","description":"One session on that computer, from its sessions list."}},"additionalProperties":false}},{"module":"machine-tools","id":"machines.session","wire":"machines_session","tier":"act","title":"Drive a session on another computer","description":"Work with one agent session on another computer this app is paired to. do: \"start\" a new session (folder and agent optional; that computer decides which folders it allows) and get its sessionId back; \"send\" a line of text (submit presses return, default true); \"keys\" presses named keys such as enter, escape, up, down, ctrl-c; \"stop\" ends it; \"rename\" sets its title; \"set\" changes its model, effort, fast mode or permission mode; \"switch-login\" restarts it as a different agent login (it gets a new sessionId); \"watch\" starts receiving its screen here so machines.look can show it (it also sizes that session to 120×30 on that computer, as opening it from a phone does). Anything done to a session you did not start, a permission-mode change and a login switch ask the person first.","index":"Start, type into, stop, rename, retune or watch a session on another paired computer.","inputSchema":{"type":"object","properties":{"machineId":{"type":"string"},"do":{"type":"string","enum":["start","send","keys","stop","rename","set","switch-login","watch"]},"sessionId":{"type":"string","description":"Required for everything except start."},"folder":{"type":"string","description":"start: the folder on that computer."},"agent":{"type":"string","enum":["claude","codex","gemini","shell"],"description":"start: which agent. Default: that computer’s own."},"text":{"type":"string","description":"send: printable text, one line."},"submit":{"type":"boolean","description":"send: press return afterwards. Default true."},"keys":{"type":"array","items":{"type":"string"},"description":"keys: pressed in order — enter, escape, tab, shift-tab, backspace, delete, space, up, down, right, left, home, end, page-up, page-down, ctrl-c, ctrl-d, ctrl-l, ctrl-u, ctrl-r, ctrl-o, ctrl-t, ctrl-a, ctrl-e, or one printable character such as \"y\" or \"2\"."},"title":{"type":"string","description":"rename: the new title. Empty puts back that computer’s own name."},"control":{"type":"string","enum":["model","effort","fast","permission"],"description":"set: which control."},"value":{"type":"string","description":"set: the value, as the session’s own picker names it."},"loginId":{"type":"string","description":"switch-login: a login id from machines.look on that machine."}},"required":["machineId","do"],"additionalProperties":false}},{"module":"machine-tools","id":"machines.copilot","wire":"machines_copilot","tier":"act","title":"Talk to Hoot on another computer","description":"Hoot on another paired computer, when that computer shares it with this one (machines.look says sharesCopilot). do: \"read\" returns its conversation and state; \"say\" sends it one line — set waitSeconds to wait for its answer, which is returned with the conversation; \"start\" starts this computer’s run on it. It acts with that computer’s own tools and asks that computer’s person before anything it may not do alone; nothing here widens that.","index":"Read, start or talk to Hoot on another paired computer, and wait for its answer.","inputSchema":{"type":"object","properties":{"machineId":{"type":"string"},"do":{"type":"string","enum":["read","say","start"]},"text":{"type":"string","description":"say: printable text, one line."},"waitSeconds":{"type":"integer","description":"say: wait up to this long for the answer, 0–120. Default 0."},"messages":{"type":"integer","description":"How many messages to return, newest last. Default 20."}},"required":["machineId","do"],"additionalProperties":false}},{"module":"machine-tools","id":"machines.ports","wire":"machines_ports","tier":"act","title":"Reach what another computer is serving","description":"The local web servers and ports on another paired computer. do: \"list\" what it is serving; \"refresh\" asks it again (after something was started there); \"open-here\" gives one of its ports an http address on this computer and returns that URL — open it in the browser like any page; \"close-here\" hands the address back; \"open-there\" opens a URL in the browser on that computer.","index":"List another paired computer’s ports, give one an address here, or open a page in its browser.","inputSchema":{"type":"object","properties":{"machineId":{"type":"string"},"do":{"type":"string","enum":["list","refresh","open-here","close-here","open-there"]},"port":{"type":"integer","description":"open-here and close-here."},"url":{"type":"string","description":"open-there."}},"required":["machineId","do"],"additionalProperties":false}},{"module":"machine-tools","id":"machines.upload","wire":"machines_upload","tier":"act","title":"Send a file to another computer","description":"Copy one file from this computer to another paired computer, into its downloads folder or a folder you name there (that computer decides whether the folder is allowed). Answers where it landed. Sending always asks the person first. do \"cancel\" stops a transfer in flight. Files under ~/.ssh and other credential folders are never sent.","index":"Copy a file from this computer to another paired computer, or cancel a transfer.","inputSchema":{"type":"object","properties":{"machineId":{"type":"string"},"do":{"type":"string","enum":["send","cancel"]},"path":{"type":"string","description":"send: absolute path of a file on this computer."},"folder":{"type":"string","description":"send: folder on that computer. Default: its downloads folder."}},"required":["machineId","do"],"additionalProperties":false}},{"module":"machine-tools","id":"machines.manage","wire":"machines_manage","tier":"alter","title":"Pair, forget or change another computer","description":"Change which computers this app is paired to and how. Every call asks the person first. do: \"pair\" with the code shown on the other computer; \"show-code\" puts a pairing code on this computer for another one to type (returned, single-use, minutes long) and \"cancel-code\" withdraws it; \"connect\" / \"disconnect\" its link; \"rename\"; \"forget\" it; \"allow-windows\" (allowed true/false) lets its sessions drive browser windows here; \"restart-host\" / \"stop-host\" its host program; \"sign-in\" / \"sign-out\" one of its agent logins (loginId from machines.look); \"github-connect\" (returns the code to type at github.com), \"github-cancel\", \"github-disconnect\" its GitHub connection.","index":"Pair, forget, rename or connect another computer; its host, agent logins and GitHub.","inputSchema":{"type":"object","properties":{"do":{"type":"string","enum":["pair","show-code","cancel-code","connect","disconnect","rename","forget","allow-windows","restart-host","stop-host","sign-in","sign-out","github-connect","github-cancel","github-disconnect"]},"machineId":{"type":"string","description":"Every verb except pair, show-code and cancel-code."},"code":{"type":"string","description":"pair: the code the other computer shows."},"name":{"type":"string","description":"rename: the new name."},"allowed":{"type":"boolean","description":"allow-windows."},"loginId":{"type":"string","description":"sign-in and sign-out."}},"required":["do"],"additionalProperties":false}},{"module":"server-room-tools","id":"servers.details","wire":"servers_details","tier":"read","title":"Read more about a server","description":"Everything on a server’s page beyond what servers.look shows. about: \"setup\" (which coding agents are on it, and whether each can be installed or signed in); \"host\" (whether this app’s host program is on it, running and linked); \"ports\" (what it listens on); \"folder\" (list a folder on it — path, default its home); \"start-in\" (the folder its terminals open in); \"grant\" (whether you have been given control of it, and until when); \"keys\" (the SSH key files on this computer that a server can be added with — names only, never their contents); \"preview\" (the exact sentence and consequence of one servers.control action, cardId and action); \"shells\" (terminals open on servers now); \"shell\" (one terminal’s screen, its agent’s model and who it is signed in as — shellId).","index":"More on a server: agent setup, host, ports, folders, SSH keys, your grant, an action’s preview, terminal screens.","inputSchema":{"type":"object","properties":{"about":{"type":"string","enum":["setup","host","ports","folder","start-in","grant","keys","preview","shells","shell"]},"serverId":{"type":"string","description":"Every about except keys, shells and shell."},"path":{"type":"string","description":"folder: the folder on the server. Default: its home."},"cardId":{"type":"string","description":"preview: from servers.look."},"action":{"type":"string","description":"preview: one of the actions servers.control takes."},"shellId":{"type":"string","description":"shell: from about \"shells\"."}},"required":["about"],"additionalProperties":false}},{"module":"server-room-tools","id":"servers.ports","wire":"servers_ports","tier":"act","title":"Reach a server’s port, or let go of a server","description":"Routine connection work on a server. do: \"open-here\" gives one of its ports an http address on this computer and returns the URL (servers.details about \"ports\" lists them); \"close-here\" hands it back; \"disconnect\" closes this app’s connection to the server once you are finished with it (its terminals stay open); \"cancel-setup\" and \"cancel-host\" stop an agent or host install that is in progress.","index":"Give a server port an address here, disconnect from a server, or cancel an install.","inputSchema":{"type":"object","properties":{"serverId":{"type":"string"},"do":{"type":"string","enum":["open-here","close-here","disconnect","cancel-setup","cancel-host"]},"port":{"type":"integer","description":"open-here and close-here."}},"required":["serverId","do"],"additionalProperties":false}},{"module":"server-room-tools","id":"servers.shell","wire":"servers_shell","tier":"alter","title":"Type into a terminal on a server","description":"A real terminal on a server, signed in as that server’s account. Whatever you type runs with that account’s full power and cannot be undone — prefer servers.control’s named actions when one fits. Every call asks the person first and shows them exactly what will be typed; being given control of a server does not change that (an outside app’s key the person set not to ask is the one exception). do: \"open\" a terminal (folder optional) and get its shellId; \"type\" one line of text (submit presses return, default true; at most 1000 characters, no newlines); \"keys\" presses named keys such as enter, ctrl-c, up; \"set\" changes the model, effort, fast or permission mode of the agent running in it; \"close\" it. Read what it shows with servers.details about \"shell\".","index":"A real terminal on a server: open, type a line, press keys, close. Every call asks the person.","inputSchema":{"type":"object","properties":{"do":{"type":"string","enum":["open","type","keys","set","close"]},"serverId":{"type":"string","description":"open."},"folder":{"type":"string","description":"open: the folder to start in. Default: the server’s start-in folder."},"shellId":{"type":"string","description":"Every do except open."},"text":{"type":"string","description":"type: one line, printable characters only."},"submit":{"type":"boolean","description":"type: press return afterwards. Default true."},"keys":{"type":"array","items":{"type":"string"},"description":"keys: pressed in order — enter, escape, tab, shift-tab, backspace, delete, space, up, down, right, left, home, end, page-up, page-down, ctrl-c, ctrl-d, ctrl-l, ctrl-u, ctrl-r, ctrl-o, ctrl-t, ctrl-a, ctrl-e, or one printable character."},"control":{"type":"string","enum":["model","effort","fast","permission"],"description":"set."},"value":{"type":"string","description":"set."}},"required":["do"],"additionalProperties":false}},{"module":"server-room-tools","id":"servers.manage","wire":"servers_manage","tier":"alter","title":"Add, change or set up a server","description":"Change the server list and what is installed on a server. Every call asks the person first. do: \"add\" a server (address, username, and either keyPath — a key file listed by servers.details about \"keys\", or \"choose\" to let the person pick one — or password; passphrase for a locked key; name and port optional); \"rename\"; \"forget\" it (its sign-in is deleted from this computer); \"revoke\" any control the person gave you over it; \"set-start-in\" the folder its terminals open in (empty to clear); \"allow-windows\" lets sessions on it drive browser windows here; \"upload\" a file from this computer to it; \"install-agent\", \"sign-in-agent\", \"sign-out-agent\", \"remove-agent\" for agent claude, codex or gemini; \"install-host\", \"pair-host\", \"link-host\" (link this computer to the host on it), \"remove-host\" (alsoData to delete its data too). Flows that type into a terminal use shellId when given, so the person can watch, and open their own otherwise.","index":"Add, rename or forget a server; upload to it; install or sign in an agent or the host on it.","inputSchema":{"type":"object","properties":{"do":{"type":"string","enum":["add","rename","forget","revoke","set-start-in","allow-windows","upload","install-agent","sign-in-agent","sign-out-agent","remove-agent","install-host","pair-host","link-host","remove-host"]},"serverId":{"type":"string","description":"Every do except add."},"address":{"type":"string","description":"add: hostname or IP."},"username":{"type":"string","description":"add."},"name":{"type":"string","description":"add (optional) and rename."},"port":{"type":"integer","description":"add: SSH port. Default 22."},"keyPath":{"type":"string","description":"add: a path from servers.details about \"keys\", or \"choose\" to have the person pick the file on this computer."},"password":{"type":"string","description":"add: the account password, when not signing in with a key."},"passphrase":{"type":"string","description":"add: the key’s passphrase, when it has one."},"remember":{"type":"boolean","description":"add: keep the sign-in after the app closes. Default true."},"folder":{"type":"string","description":"set-start-in."},"allowed":{"type":"boolean","description":"allow-windows."},"path":{"type":"string","description":"upload: absolute path of a file on this computer."},"agent":{"type":"string","enum":["claude","codex","gemini"],"description":"The agent verbs."},"shellId":{"type":"string","description":"Terminal flows: run in this open terminal."},"alsoData":{"type":"boolean","description":"remove-host: also delete its data."}},"required":["do"],"additionalProperties":false}},{"module":"remote-tools","id":"remote.status","wire":"remote_status","tier":"read","title":"Who can reach this computer","description":"Remote access to this computer: whether it is on and connected to the relay, every phone and computer paired with it (as the owner’s own, or a guest), what each may reach — folders, sessions, agent logins, browser windows — who is connected right now and what they have open, the sessions here that devices are offered, whether this computer is kept awake, and whether sessions started from a device are held to their folder. Set tailscale true to include the optional Tailscale direct route, which this app never needs.","index":"Who can reach this computer: remote access, paired phones and computers, who is connected.","inputSchema":{"type":"object","properties":{"tailscale":{"type":"boolean","description":"Also report the optional Tailscale route. Default false."}},"additionalProperties":false}},{"module":"remote-tools","id":"remote.manage","wire":"remote_manage","tier":"alter","title":"Change who can reach this computer","description":"Grant, narrow or take away remote access to this computer. Every call asks the person first. do: \"start\" / \"stop\" remote access as a whole (stop cuts off every connected device); \"show-code\" puts a six-digit pairing code on this computer for a phone or computer to type (returned; single-use, minutes long) and \"cancel-code\" withdraws it; \"approve\" a waiting device (kind \"mine\" for the owner’s own, or \"guest\" with folders and loginShare/logins); \"revoke\" a device; \"set-folders\" (a guest’s folders), \"set-accounts\" (loginShare all or selected, logins), \"set-sessions\" (sessionShare all or selected, sessions), \"set-windows\" (allowed) change what one device may reach; \"disconnect\" one connection now; \"stop-tunnel\" one port a connection opened; \"keep-awake\" (on) keeps this computer from sleeping with the lid closed — turning it on shows macOS’s own administrator password prompt on this computer’s screen.","index":"Turn remote access on or off, pair, approve or revoke a device, or change what it may reach.","inputSchema":{"type":"object","properties":{"do":{"type":"string","enum":["start","stop","show-code","cancel-code","approve","revoke","set-folders","set-accounts","set-sessions","set-windows","disconnect","stop-tunnel","keep-awake"]},"deviceId":{"type":"string","description":"approve, revoke and the set- verbs. From remote.status."},"kind":{"type":"string","enum":["mine","guest"],"description":"approve."},"folders":{"type":"array","items":{"type":"string"},"description":"approve (guest) and set-folders: absolute folders on this computer."},"loginShare":{"type":"string","enum":["all","selected"],"description":"approve (guest) and set-accounts."},"logins":{"type":"array","items":{"type":"string"},"description":"Login ids, when loginShare is selected."},"sessionShare":{"type":"string","enum":["all","selected"],"description":"set-sessions."},"sessions":{"type":"array","items":{"type":"string"},"description":"Session ids, when sessionShare is selected."},"allowed":{"type":"boolean","description":"set-windows."},"connectionId":{"type":"string","description":"disconnect and stop-tunnel."},"tunnelId":{"type":"string","description":"stop-tunnel."},"on":{"type":"boolean","description":"keep-awake."}},"required":["do"],"additionalProperties":false}},{"module":"device-tools","id":"devices.list","wire":"devices_list","tier":"read","title":"List phones and simulators","description":"Every iOS Simulator and Android emulator on this computer, running or not, and every Android phone plugged in by USB. Each row has the id every other devices tool takes, its name, platform, kind (simulator, emulator or physical), its state in words, whether it is usable right now, its OS version, whether devices.open can start it, and which hardware buttons, named keys and text it accepts (text: unicode, ascii or none). Call this first. Positions in every devices tool are fractions of the screen, 0 to 1, x from the left and y from the top.","index":"The iOS Simulators, Android emulators and USB Android phones on this computer, with the id every devices tool takes. Call first.","inputSchema":{"type":"object","properties":{},"additionalProperties":false}},{"module":"device-tools","id":"devices.open","wire":"devices_open","tier":"act","title":"Start and open a device","description":"Get a device ready to drive: starts a simulator or emulator that is off — that can take a minute or more — and opens it so later taps, typing and screen reads answer quickly. Returns its details (name, screen size in points, buttons, keys, text it accepts, whether it rotates) and the id to use from now on: an Android emulator listed as avd:<name> while it was off becomes android:emulator-<port> once it runs. A phone on a cable cannot be started from here. Every other devices tool opens a running device by itself, so this is only needed for one that is off.","index":"Start a simulator or emulator that is off and open it for driving; answers the id to use from then on.","inputSchema":{"type":"object","properties":{"deviceId":{"type":"string","description":"The device’s id from devices.list, such as ios:… or android:…."}},"required":["deviceId"],"additionalProperties":false}},{"module":"device-tools","id":"devices.shutdown","wire":"devices_shutdown","tier":"act","title":"Shut a simulator down","description":"Shut down a running iOS Simulator or Android emulator, as its own Shut Down would; anything unsaved in its apps is lost. It never works on a phone plugged in by USB — a person turns their phone off on the phone. devices.open starts it again.","index":"Shut down a running iOS Simulator or Android emulator; a phone on a cable is never powered off from here.","inputSchema":{"type":"object","properties":{"deviceId":{"type":"string","description":"The device’s id from devices.list, such as ios:… or android:…."}},"required":["deviceId"],"additionalProperties":false}},{"module":"device-tools","id":"devices.screenshot","wire":"devices_screenshot","tier":"read","title":"Photograph a device screen","description":"A full-resolution PNG of the device’s screen, saved in the Pictures folder of the computer running this app. Returns the path and the size in pixels, never the image. To decide what to tap use devices.tree or devices.find — they give names and positions; a picture is for a person to look at, or for checking how something looks.","index":"Save a full-resolution PNG of a device’s screen to the Pictures folder; answers the path and size, not the image.","inputSchema":{"type":"object","properties":{"deviceId":{"type":"string","description":"The device’s id from devices.list, such as ios:… or android:…."}},"required":["deviceId"],"additionalProperties":false}},{"module":"device-tools","id":"devices.tap","wire":"devices_tap","tier":"act","title":"Tap a device screen","description":"Tap one point, or tap an element found by name. Give x and y — fractions of the screen, 0 to 1, x across from the left and y down from the top, whichever way up the device is — or give name, identifier and/or role, and the screen is read fresh and the one element that matches is tapped at its centre. If nothing matches, or several different elements do, nothing is tapped and the answer lists up to 5 candidates with their centres. holdMs of 400 or more makes it a long press (at most 5000). Returns where it tapped and what was there.","index":"Tap a device screen at a position, or on an element found by name or identifier; holdMs makes it a long press.","inputSchema":{"type":"object","properties":{"deviceId":{"type":"string","description":"The device’s id from devices.list, such as ios:… or android:…."},"x":{"type":"number","description":"Across, from 0 (left edge) to 1 (right edge)."},"y":{"type":"number","description":"Down, from 0 (top edge) to 1 (bottom edge)."},"name":{"type":"string","description":"What the element says or is labelled, matched whole and ignoring case unless partial is true."},"identifier":{"type":"string","description":"Its accessibility identifier or test id."},"role":{"type":"string","description":"Plain words such as button or text field, or the platform’s own role."},"partial":{"type":"boolean","description":"Match name anywhere inside the element’s text."},"holdMs":{"type":"number","description":"Hold this long. 400 or more is a long press; at most 5000."}},"required":["deviceId"],"additionalProperties":false}},{"module":"device-tools","id":"devices.swipe","wire":"devices_swipe","tier":"act","title":"Swipe on a device screen","description":"Drag a finger across the screen. Give from and to, each {x, y} as fractions of the screen (0 to 1, x from the left, y from the top), with an optional durationMs (default 300; slower is a drag, faster a flick). Or give direction for an ordinary scroll: direction is the way the finger travels, so up drags from low on the screen to high, moving the content up to show what is further down a list; down goes back towards the top; left and right page sideways the same way.","index":"Swipe or scroll on a device screen, between two points or simply up, down, left or right.","inputSchema":{"type":"object","properties":{"deviceId":{"type":"string","description":"The device’s id from devices.list, such as ios:… or android:…."},"from":{"type":"object","description":"A point as fractions of the screen: {\"x\": 0..1 from the left, \"y\": 0..1 from the top}.","properties":{"x":{"type":"number"},"y":{"type":"number"}}},"to":{"type":"object","description":"A point as fractions of the screen: {\"x\": 0..1 from the left, \"y\": 0..1 from the top}.","properties":{"x":{"type":"number"},"y":{"type":"number"}}},"durationMs":{"type":"number","description":"How long the finger takes, 50 to 5000. Default 300."},"direction":{"type":"string","enum":["up","down","left","right"],"description":"Instead of from and to: the way the finger travels. up shows what is further down a list."}},"required":["deviceId"],"additionalProperties":false}},{"module":"device-tools","id":"devices.type","wire":"devices_type","tier":"act","title":"Type on a device","description":"Type text into whatever field has focus on the device, and/or press one named key — return, enter, delete, tab, escape, the arrows or select-all — with optional modifiers. Tap the field with devices.tap first. The text is typed before the key is pressed, so {text, key: \"return\"} fills a field and submits it. Only the text’s length is written to the activity log, never the text, so a password can be typed. Up to 2000 characters at once. Some devices take plain ASCII only; devices.list says which.","index":"Type text into the focused field on a device and/or press a key such as return; the text itself is never logged.","inputSchema":{"type":"object","properties":{"deviceId":{"type":"string","description":"The device’s id from devices.list, such as ios:… or android:…."},"text":{"type":"string","description":"Typed into the focused field. Up to 2000 characters."},"key":{"type":"string","enum":["delete","return","enter","tab","escape","arrow-up","arrow-down","arrow-left","arrow-right","select-all"],"description":"A key pressed after the text, if any."},"modifiers":{"type":"array","items":{"type":"string","enum":["command","shift","option","control"]},"description":"Held while key is pressed."}},"required":["deviceId"],"additionalProperties":false}},{"module":"device-tools","id":"devices.button","wire":"devices_button","tier":"act","title":"Press a button or rotate a device","description":"Press a hardware button — home, back, overview, lock, volume-up, volume-down, action — or turn the device to an orientation: portrait, landscape-left, landscape-right, portrait-upside-down. Give one of button or rotate. Not every device has every button or can turn: devices.list shows what each has, and a button it does not have is refused rather than pressed. Returns what was pressed, or the orientation it is in now.","index":"Press a hardware button (home, back, lock, volume and so on) on a device, or turn it to portrait or landscape.","inputSchema":{"type":"object","properties":{"deviceId":{"type":"string","description":"The device’s id from devices.list, such as ios:… or android:…."},"button":{"type":"string","enum":["home","back","overview","lock","volume-up","volume-down","action"]},"rotate":{"type":"string","enum":["portrait","landscape-left","landscape-right","portrait-upside-down"],"description":"Turn the device to this orientation."}},"required":["deviceId"],"additionalProperties":false}},{"module":"device-tools","id":"devices.tree","wire":"devices_tree","tier":"read","title":"Read what is on a device screen","description":"What the device is showing, as a list of elements in reading order: each with its role in plain words, its name, its accessibility identifier or test id, its value (never a password’s — that is marked secret), enabled: false when it is greyed out, and its frame and centre as fractions of the screen (0 to 1, x from the left, y from the top) — the centre is exactly what devices.tap takes, and an element scrolled off the screen is marked offScreen instead of having one. depth says how deeply it sits inside the rows above it. A React Native app in development also names each element’s component and source file. Also says which app and screen are in front. scope: interactive lists only what can be acted on, visible (default) what is on screen, full also what is scrolled away. At most limit elements (default 150); truncated says when there were more.","index":"Read what is on a device screen: each element’s role, name, identifier and centre to tap, and the app in front.","inputSchema":{"type":"object","properties":{"deviceId":{"type":"string","description":"The device’s id from devices.list, such as ios:… or android:…."},"scope":{"type":"string","enum":["interactive","visible","full"],"description":"interactive: only what can be acted on. visible (default): what is on screen. full: also what is scrolled away."},"limit":{"type":"integer","description":"Most elements listed. Default 150, at most 400."}},"required":["deviceId"],"additionalProperties":false}},{"module":"device-tools","id":"devices.find","wire":"devices_find","tier":"read","title":"Find elements on a device screen","description":"Find elements on the screen by name, identifier and/or role, and get each match’s centre and frame, so you can tap it by its centre or by the same name with devices.tap. name is matched against what the element says and its accessibility label, whole and ignoring case unless partial is true. role takes plain words (button, text field) or the platform’s own (AXButton). At most 20 matches. A match scrolled off the screen is marked offScreen and has no centre: swipe to it first.","index":"Find elements on a device screen by name, identifier or role, with the centre of each one to tap.","inputSchema":{"type":"object","properties":{"deviceId":{"type":"string","description":"The device’s id from devices.list, such as ios:… or android:…."},"name":{"type":"string","description":"What the element says or is labelled, matched whole and ignoring case unless partial is true."},"identifier":{"type":"string","description":"Its accessibility identifier or test id."},"role":{"type":"string","description":"Plain words such as button or text field, or the platform’s own role."},"partial":{"type":"boolean","description":"Match name anywhere inside the element’s text."},"scope":{"type":"string","enum":["interactive","visible","full"],"description":"As in devices.tree. Default visible."}},"required":["deviceId"],"additionalProperties":false}},{"module":"device-tools","id":"devices.annotations","wire":"devices_annotations","tier":"read","title":"Read what a person annotated","description":"What a person marked with Annotate — on a phone or simulator screen, or on a browser page; both kinds are kept here. Each round says where it was made (the device and app, or the page address), the path of the picture with numbered markers drawn on it, which session it was sent to if any, the one note the person wrote about the whole round (it refers to markers by number, \"#2\"), and each marker by its number with the element it is on — its name, identifier, component and source file when known — and its rectangle as fractions of the picture. Newest first. count (default 1, at most 10) and kind (device or browser) narrow it. Only rounds made since the app last started.","index":"Read what a person marked with Annotate on a device screen or a browser page: the numbered elements, their one note, the marked picture.","inputSchema":{"type":"object","properties":{"count":{"type":"integer","description":"How many rounds, newest first. Default 1, at most 10."},"kind":{"type":"string","enum":["device","browser"],"description":"Only rounds made on a device screen, or only on a browser page."}},"additionalProperties":false}},{"module":"worker-tools","id":"browser.workers","wire":"browser_workers","tier":"read","title":"List the browser’s worker profiles","description":"The worker profiles this browser has, each with its own cookie jar: which are free, which of your windows is showing a page in each one right now, which sites each has been signed into this run, and how many may run at once. A worker with no window of yours cannot be driven — the person opens a page in it and attaches the window. Nothing here reads a cookie or a value.","index":"The browser's worker profiles — separate cookie jars — which are free, and which sites each has signed into this run.","inputSchema":{"type":"object","properties":{},"additionalProperties":false}},{"module":"worker-tools","id":"browser.worker","wire":"browser_worker","tier":"act","title":"Take or release a worker profile","description":"take holds one worker and does not answer until its wait has been served, so the gap between requests is real rather than something you have to remember. release hands it back. renew keeps a long piece of work from lapsing. A hold lapses on its own if you stop renewing it, so a worker is never stuck because an agent went away.","index":"Take, renew or release one worker profile, so two agents never drive one cookie jar and the wait between requests is actually served.","inputSchema":{"type":"object","properties":{"action":{"type":"string","enum":["take","release","renew"],"description":"take: hold one worker and serve its wait before answering. release: hand it back. renew: keep it a while longer."},"worker":{"type":"string","description":"The worker’s name, from browser.workers. Omit on take to be given whichever has been idle longest."},"holdMs":{"type":"number","description":"How long the hold lasts before it lapses on its own. Default 120000, max 600000."}},"required":["action"],"additionalProperties":false}}]
